const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('#nav');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('span').textContent=open?'−':'+';nav.classList.toggle('open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){toggle.setAttribute('aria-expanded','false');toggle.querySelector('span').textContent='+';nav.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.querySelector('span').textContent='+';toggle.focus()}});document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;document.querySelectorAll('.course').forEach(course=>{course.hidden=button.dataset.filter!=='all'&&course.dataset.category!==button.dataset.filter;if(!course.hidden)count++});document.querySelector('#course-status').textContent=`${count} courses shown`}));document.querySelector('#year').textContent=new Date().getFullYear();
